from pathlib import Path
import base64,hashlib,json,os,subprocess,fcntl,time
root=Path('/data/research-user/h3_inference_20261023/live_phase_pair_20261023/probe_identity_2507a9b0')
root.mkdir(exist_ok=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
files={'POLICY.json': '', 'core.py': '', 'run.py': '', 'test_diagnostic.py': '', 'README.md': '', 'HANDOFF.txt': '', 'inputs.remote.json': '', 'TEST_RESULTS.json': '', 'READY.json': '', 'SIGNOFF.json': '', 'ROOT_RELEASE.json': ''}
with (root/'execution.lock').open('a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 for n,b in files.items():
  raw=base64.b64decode(b);p=root/n
  if p.exists():assert p.read_bytes()==raw,n
  else:p.write_bytes(raw)
 ready=json.loads((root/'READY.json').read_text());release=json.loads((root/'ROOT_RELEASE.json').read_text())
 assert sha(root/'READY.json')==release['ready_sha256'] and sha(root/'SIGNOFF.json')==release['signoff_sha256']
 for n,h in ready['files_sha256'].items():assert sha(root/n)==h,n
 out=root/'result_20261023'
 if not out.exists():
  assert not (root/'STARTED.json').exists(),'Prior execution requires reconciliation'
  (root/'STARTED.json').write_text(json.dumps({'pid':os.getpid(),'uid':os.getuid(),'time':time.time(),'scope':'CPU only; existing arrays; no model/GPU'})+'\n')
  env=dict(os.environ,CUDA_VISIBLE_DEVICES='',OMP_NUM_THREADS='2',OPENBLAS_NUM_THREADS='2',MKL_NUM_THREADS='2')
  r=subprocess.run(['/data/research-user/h3_inference_20261023/env/bin/python',str(root/'run.py'),'--inputs',str(root/'inputs.remote.json'),'--output',str(out)],cwd=root,env=env,capture_output=True,text=True,timeout=120)
  (root/'EXECUTION.json').write_text(json.dumps({'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'time':time.time()},indent=2)+'\n')
  assert r.returncode==0,r.stderr
 status=json.loads((out/'STATUS.json').read_text());assert status['status']=='complete',status
 assert sha(out/'summary.json')==status['summary_sha256']
 print(json.dumps({'remote_root':str(root),'status':status,'summary':json.loads((out/'summary.json').read_text())}))
